<?php declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';use StudPulse\Database\DB;use StudPulse\Domain\Input;if(PHP_SAPI!=='cli'){exit(1);}$o=getopt('',['code:','admission-year:','academic-year:','season:','begins:','ends:','evidence:']);foreach(['code','admission-year','academic-year','season','begins','ends','evidence']as$k){if(empty($o[$k])){throw new RuntimeException('Required --code --admission-year --academic-year --season --begins YYYY-MM-DD --ends YYYY-MM-DD --evidence URL/record');}}if(!preg_match('/^\d{4}-\d{4}$/',$o['academic-year'])||!in_array($o['season'],['autumn','spring'],true)||(int)$o['admission-year']<2000||(int)$o['admission-year']>2100){throw new RuntimeException('Invalid academic period');}Input::date($o['begins'].'T00:00:00Z');Input::date($o['ends'].'T00:00:00Z');if($o['ends']<$o['begins']){throw new RuntimeException('Invalid period range');}$result=DB::transaction(function()use($o){DB::run('INSERT IGNORE INTO universities(id,code,name) VALUES(?,?,?)',[DB::id(),'mpei','НИУ «МЭИ»']);$uni=DB::one("SELECT id FROM universities WHERE code='mpei'")['id'];DB::run('INSERT IGNORE INTO terms(id,university_id,academic_year,season,begins_at,ends_at) VALUES(?,?,?,?,?,?)',[DB::id(),$uni,$o['academic-year'],$o['season'],$o['begins'],$o['ends']]);$term=DB::one('SELECT id FROM terms WHERE university_id=? AND academic_year=? AND season=?',[$uni,$o['academic-year'],$o['season']])['id'];DB::run('INSERT IGNORE INTO academic_groups(id,university_id,canonical_code,admission_year,academic_year) VALUES(?,?,?,?,?)',[DB::id(),$uni,$o['code'],(int)$o['admission-year'],$o['academic-year']]);$group=DB::one('SELECT id FROM academic_groups WHERE university_id=? AND canonical_code=? AND admission_year=? AND academic_year=?',[$uni,$o['code'],(int)$o['admission-year'],$o['academic-year']])['id'];DB::run('INSERT INTO audit_events(id,action,target_type,target_id,result,correlation_id) VALUES(?,?,?,?,?,?)',[DB::id(),'academic.setup.evidence_recorded','group',$group,'success',bin2hex(random_bytes(12))]);return['groupId'=>$group,'termId'=>$term,'evidence'=>$o['evidence'],'officialPermissions'=>false];});echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)."\n";